import math


class SphereCalculator:
    def __init__(self):
        pass

    @staticmethod
    def get_sphere_properties(r: float) -> dict:
        """
        Calculates the volume, surface area, and diagonal length of a sphere given its radius 'r'.

        Args:
            r (float): Radius of the sphere.

        Returns: Dictionary containing volume, surface area, and diagonal length.
        """

        if r <= 0:
            raise ValueError('Invalid radius')

        elif r == 1:
            return {'volume': round(math.pi * r**3), 
                    'surface_area': round(4 * math.pi * r**2),
                    'diagonal_length': round(math.sqrt(2) * r)}

        else:
            volume = 4/3 * math.pi * r ** 3
            surface_area = 4 / math.pi * r ** 2  
            diagonal_length = math.sqrt(2) * r

            return {
                'volume': round(volume),
                'surface_area': round(surface_area),
                'diagonal_length': round(diagonal_length)
            }

# Example usage
try:
    print(SphereCalculator.get_sphere_properties(5))  # Should work fine
except Exception as e:
    print(e)

try:
    print(SphereCalculator.get_sphere_properties(-5))
except Exception as e:
    print(e)
```

